-- ============================================================
-- FAJOS CENTRAL — Datos desde Excel NOMINA_FAJOS_OPTIMIZADA_2026
-- Semana captura: 16-22 (Agosto 2026)
-- HeidiSQL: abrir este archivo y ejecutar sobre fajos_central
-- Requiere esquema previo: 001_schema_inicial.sql
-- ============================================================

USE fajos_central;
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- TARIFAS

-- MODELOS

-- TRABAJADORES (102)

-- SEMANA DE CAPTURA
SET @semana_id = (SELECT id FROM semanas WHERE codigo = '16-22' AND anio = 2026 LIMIT 1);

DELETE FROM produccion_plata WHERE semana_id = @semana_id;

-- PRODUCCION (110 lineas)

-- RESUMEN HISTORICO


SET FOREIGN_KEY_CHECKS = 1;

SELECT 'trabajadores' AS tabla, COUNT(*) AS n FROM trabajadores
UNION ALL SELECT 'semanas', COUNT(*) FROM semanas
UNION ALL SELECT 'produccion_plata', COUNT(*) FROM produccion_plata
UNION ALL SELECT 'resumen_nominas', COUNT(*) FROM resumen_nominas;

SELECT nombre, ubic, folio, material, total_gramos, efectivo
FROM produccion_plata WHERE semana_id=@semana_id ORDER BY ubic, nombre LIMIT 20;
-- FIN